pragma solidity ^0.8.24;

/// @title BiggiCapsLib
/// @notice Shared cap constants for BIGGI root + TOKENOMICMAINNET branches.
library BiggiCapsLib {
    /// @notice Global BIGGI max supply including guardian refill budgets.
    uint256 public constant BIGGI_TOTAL_SUPPLY = 2_200_000_000 * 1e18;

    /// @notice Initial allocation for DripDistributor in initialDistribute().
    uint256 public constant DRIP_DISTRIBUTOR_CAP = 200_000_000 * 1e18;

    /// @notice Initial allocation for TokenRewards in initialDistribute().
    uint256 public constant TOKEN_REWARDS_CAP = 200_000_000 * 1e18;

    /// @notice Initial marketing allocation in initialDistribute().
    uint256 public constant MARKETING_SUPPORT_INITIAL = 200_000_000 * 1e18;

    /// @notice Initial/target reserve allocation (pairing + liquidity).
    uint256 public constant RESERVE_INITIAL = 600_000_000 * 1e18;

    /// @notice Extra guardian budget for DEX/drip refill branch.
    uint256 public constant GUARDIAN_DEX_MINT_CAP = 500_000_000 * 1e18;

    /// @notice Extra guardian budget for token rewards refill branch.
    uint256 public constant GUARDIAN_REWARDS_MINT_CAP = 500_000_000 * 1e18;

    /// @notice Historical max tokens DripDistributor can receive.
    uint256 public constant DRIP_DISTRIBUTOR_TOTAL_CAP = DRIP_DISTRIBUTOR_CAP + GUARDIAN_DEX_MINT_CAP;

    /// @notice Historical max tokens TokenRewards can receive from refill model.
    uint256 public constant TOKEN_REWARDS_TOTAL_CAP = TOKEN_REWARDS_CAP + GUARDIAN_REWARDS_MINT_CAP;
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

import "./Library/BiggiErrorsLib.sol";
import "./Library/BiggiCapsLib.sol";

/// @notice Účetní kontrakt držící BIGGI pro DripLM.
/// - CAP nezávislý na treasury (DRIP_DISTRIBUTOR_CAP)
/// - whitelist kolekcí pro notifyMint (accounting)
contract BiggiDripDistributor is Ownable, ReentrancyGuard, Pausable {
    using SafeERC20 for IERC20;

    IERC20 public immutable BIGGI;

    address public dripLM;
    address public treasury;

    // volitelný operator (např. DripLM), který může dynamicky přepisovat tokensPerMint
    address public tokensPerMintOperator;

    // kolik BIGGI (raw) se účetně alokuje za 1 mint
    uint256 public tokensPerMint;

    // účetní stav (claimovatelné)
    uint256 public availableTokens;

    // kumulativní statistiky
    uint256 public totalReceived;
    uint256 public totalClaimed;
    uint256 public totalNotified;
    bool public historicalStateSeeded;

    uint256 public constant CAP = BiggiCapsLib.DRIP_DISTRIBUTOR_TOTAL_CAP;

    mapping(address => bool) public collections;

    /* ===== events ===== */
    event CollectionSet(address indexed coll, bool allowed);
    event DripLMSet(address indexed oldLM, address indexed newLM);
    event TreasurySet(address indexed oldT, address indexed newT);
    event TokensPerMintOperatorSet(address indexed oldOp, address indexed newOp);
    event TokensPerMintSet(uint256 oldVal, uint256 newVal);

    event NotifyMint(address indexed coll, uint256 count, uint256 tokensAdded);
    event Claimed(address indexed to, uint256 amount);

    event TopUp(address indexed from, uint256 amount);
    event NotifyTokenMint(address indexed tokenContract, uint256 amount);
    event HistoricalStateSeeded(
        uint256 totalReceived,
        uint256 totalClaimed,
        uint256 totalNotified,
        uint256 availableTokens
    );

    event RescueERC20(address token, address to, uint256 amount);
    event RescueNative(address to, uint256 amount);

    modifier onlyDripLM() {
        if (msg.sender != dripLM) revert BiggiErrorsLib.OnlyDripLM();
        _;
    }

    modifier onlyTreasury() {
        if (msg.sender != treasury) revert BiggiErrorsLib.OnlyTreasury();
        _;
    }

    constructor(address token_, address initialOwner) Ownable(initialOwner) {
        if (token_ == address(0) || initialOwner == address(0)) {
            revert BiggiErrorsLib.ZeroAddress();
        }
        BIGGI = IERC20(token_);
    }

    /* ===== admin setters ===== */

    function syncAvailableToBalance() external onlyOwner whenNotPaused {
        uint256 bal = BIGGI.balanceOf(address(this));
        availableTokens = bal;
    }

    function setCollection(address coll, bool allowed) external onlyOwner {
        if (coll == address(0)) revert BiggiErrorsLib.ZeroAddress();
        collections[coll] = allowed;
        emit CollectionSet(coll, allowed);
    }

    function setDripLM(address lm) external onlyOwner {
        if (lm == address(0)) revert BiggiErrorsLib.ZeroAddress();
        emit DripLMSet(dripLM, lm);
        dripLM = lm;
    }

    function setTreasury(address t) external onlyOwner {
        if (t == address(0)) revert BiggiErrorsLib.ZeroAddress();
        emit TreasurySet(treasury, t);
        treasury = t;
    }

    function setTokensPerMintOperator(address op) external onlyOwner {
        emit TokensPerMintOperatorSet(tokensPerMintOperator, op);
        tokensPerMintOperator = op;
    }

    /// @notice Owner nastaví tokensPerMint v raw jednotkách (např. 1000 * 1e18)
    function setTokensPerMint(uint256 v) external onlyOwner {
        emit TokensPerMintSet(tokensPerMint, v);
        tokensPerMint = v;
    }

    /// @notice Operator (např. DripLM) může dynamicky přepsat tokensPerMint podle buybacku
    function setTokensPerMintFromOperator(uint256 v) external {
        require(msg.sender == tokensPerMintOperator, "not operator");
        emit TokensPerMintSet(tokensPerMint, v);
        tokensPerMint = v;
    }

    function seedHistoricalState(
        uint256 totalReceived_,
        uint256 totalClaimed_,
        uint256 totalNotified_,
        uint256 availableTokens_
    ) external onlyOwner {
        require(!historicalStateSeeded, "already seeded");
        totalReceived = totalReceived_;
        totalClaimed = totalClaimed_;
        totalNotified = totalNotified_;
        availableTokens = availableTokens_;
        historicalStateSeeded = true;
        emit HistoricalStateSeeded(totalReceived_, totalClaimed_, totalNotified_, availableTokens_);
    }

    function pause() external onlyOwner { _pause(); }
    function unpause() external onlyOwner { _unpause(); }

    /* ===== notify from collection (accounting only) ===== */
    function notifyMint(uint256 mintedCount) external nonReentrant whenNotPaused {
        if (mintedCount == 0) revert BiggiErrorsLib.AmountZero();
        if (!collections[msg.sender]) revert BiggiErrorsLib.NotWhitelistedCollection();

        uint256 add = tokensPerMint * mintedCount;
        availableTokens += add;
        totalNotified += add;

        emit NotifyMint(msg.sender, mintedCount, add);
    }

    /* ===== token contract notification (initial/top-up) ===== */
    function notifyTokenMint(uint256 amount) external nonReentrant whenNotPaused {
        if (amount == 0) revert BiggiErrorsLib.AmountZero();
        if (msg.sender != address(BIGGI)) revert BiggiErrorsLib.OnlyToken();
        if (totalReceived + amount > CAP) revert BiggiErrorsLib.CapExceeded();

        uint256 netHeld = totalReceived >= totalClaimed ? (totalReceived - totalClaimed) : 0;
        uint256 bal = BIGGI.balanceOf(address(this));
        require(bal >= netHeld + amount, "token not transferred");

        totalReceived += amount;
        availableTokens += amount;

        emit NotifyTokenMint(msg.sender, amount);
        emit TopUp(msg.sender, amount);
    }

    /* ===== treasury deposit (TopUp) ===== */
    function depositTokens(uint256 amount) external nonReentrant whenNotPaused onlyTreasury {
        if (amount == 0) revert BiggiErrorsLib.AmountZero();
        if (totalReceived + amount > CAP) revert BiggiErrorsLib.CapExceeded();

        BIGGI.safeTransferFrom(msg.sender, address(this), amount);

        totalReceived += amount;
        availableTokens += amount;

        emit TopUp(msg.sender, amount);
    }
    // supply-controller top-ups are routed through BIGGI.notifyTokenMint(amount)

    /* ===== claim by DripLM ===== */
    function claim(uint256 amountRequested) external nonReentrant onlyDripLM whenNotPaused {
        if (amountRequested == 0) revert BiggiErrorsLib.AmountZero();

        uint256 bal = BIGGI.balanceOf(address(this));
        uint256 toSend = amountRequested;

        if (toSend > availableTokens) toSend = availableTokens;
        if (toSend > bal) toSend = bal;

        if (toSend == 0) revert BiggiErrorsLib.NoneAvailable();

        availableTokens -= toSend;
        totalClaimed += toSend;

        BIGGI.safeTransfer(msg.sender, toSend);
        emit Claimed(msg.sender, toSend);
    }

    function claimTo(address to, uint256 amountRequested) external nonReentrant onlyDripLM whenNotPaused {
        if (to == address(0)) revert BiggiErrorsLib.ToZero();
        if (amountRequested == 0) revert BiggiErrorsLib.AmountZero();

        uint256 bal = BIGGI.balanceOf(address(this));
        uint256 toSend = amountRequested;

        if (toSend > availableTokens) toSend = availableTokens;
        if (toSend > bal) toSend = bal;

        if (toSend == 0) revert BiggiErrorsLib.NoneAvailable();

        availableTokens -= toSend;
        totalClaimed += toSend;

        BIGGI.safeTransfer(to, toSend);
        emit Claimed(to, toSend);
    }

    /* ===== rescue & helpers ===== */
    function rescueERC20(address token, address to, uint256 amount) external onlyOwner {
        if (to == address(0)) revert BiggiErrorsLib.ToZero();
        IERC20(token).safeTransfer(to, amount);
        emit RescueERC20(token, to, amount);
    }

    function rescueNative(address payable to, uint256 amount) external onlyOwner {
        if (to == address(0)) revert BiggiErrorsLib.ToZero();
        (bool ok, ) = to.call{value: amount}("");
        require(ok, "native xfer fail");
        emit RescueNative(address(to), amount);
    }

    receive() external payable {}

    /* ===== view helpers ===== */

    function biggiBalance() public view returns (uint256) {
        return BIGGI.balanceOf(address(this));
    }

    function effectiveAvailable() public view returns (uint256) {
        uint256 bal = BIGGI.balanceOf(address(this));
        return availableTokens <= bal ? availableTokens : bal;
    }

    function getAvailable() external view returns (uint256) { return availableTokens; }
    function getTotalNotified() external view returns (uint256) { return totalNotified; }
    function getTotalClaimed() external view returns (uint256) { return totalClaimed; }
    function getTotalReceived() external view returns (uint256) { return totalReceived; }
    function isCollection(address a) external view returns (bool) { return collections[a]; }

    function capRemaining() external view returns (uint256) {
        if (totalReceived >= CAP) return 0;
        return CAP - totalReceived;
    }

    struct Snapshot {
        address token;
        address dripLM;
        address treasury;
        address operator;
        uint256 tokensPerMint;
        uint256 available;
        uint256 effectiveAvailable;
        uint256 totalReceived;
        uint256 totalClaimed;
        uint256 totalNotified;
        uint256 cap;
        uint256 capRemaining;
        uint256 balance;
        bool paused;
    }

    function snapshot() external view returns (Snapshot memory s) {
        s.token = address(BIGGI);
        s.dripLM = dripLM;
        s.treasury = treasury;
        s.operator = tokensPerMintOperator;
        s.tokensPerMint = tokensPerMint;

        s.available = availableTokens;

        uint256 bal = BIGGI.balanceOf(address(this));
        s.balance = bal;
        s.effectiveAvailable = availableTokens <= bal ? availableTokens : bal;

        s.totalReceived = totalReceived;
        s.totalClaimed = totalClaimed;
        s.totalNotified = totalNotified;

        s.cap = CAP;
        s.capRemaining = totalReceived >= CAP ? 0 : (CAP - totalReceived);
        s.paused = paused();
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/ERC20Burnable.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/ERC20Permit.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

import "./Library/BiggiCapsLib.sol";

interface IBiggiDripDistributorNotify {
    function notifyTokenMint(uint256 amount) external;
}

contract BiggiToken is ERC20, ERC20Burnable, ERC20Permit, Pausable, Ownable {
    using SafeERC20 for IERC20;

    uint256 public constant CAP = BiggiCapsLib.BIGGI_TOTAL_SUPPLY;

    address public reserveAddr;
    address public dripDistributorAddr;
    address public tokenRewardsAddr;
    address public marketingSupportAddr;
    address public rewardsOperator;
    address public supplyController;
    address public supplyGuardian; // optional manual guardian helper; same authority class as controller

    bool public distributed;
    bool public guardianMintPaused;

    uint256 public guardianDexMinted;
    uint256 public guardianRewardsMinted;

    event InitialDistribution(
        address indexed reserve,
        address indexed dripDistributor,
        address indexed tokenRewards,
        address marketingSupport,
        uint256 reserveAmt,
        uint256 dripAmt,
        uint256 rewardsAmt,
        uint256 marketingAmt
    );
    event ReserveSet(address indexed oldAddr, address indexed newAddr);
    event DripDistributorSet(address indexed oldAddr, address indexed newAddr);
    event TokenRewardsSet(address indexed oldAddr, address indexed newAddr);
    event MarketingSupportSet(address indexed oldAddr, address indexed newAddr);
    event RewardsOperatorSet(address indexed oldOp, address indexed newOp);
    event SupplyControllerSet(address indexed oldController, address indexed newController);
    event SupplyGuardianSet(address indexed oldGuardian, address indexed newGuardian);
    event GuardianMintPauseSet(bool paused);
    event RewardsRefilled(uint256 beforeBal, uint256 afterBal, uint256 minted);
    event RescueERC20(address token, address to, uint256 amount);
    event ReserveTransfer(address indexed to, uint256 amount, address indexed caller);
    event GuardianDexMint(address indexed to, uint256 amount, uint256 mintedTotal);
    event GuardianRewardsMint(address indexed to, uint256 amount, uint256 mintedTotal);

    constructor(address initialOwner)
        ERC20("Biggi Token", "BIGGI")
        ERC20Permit("Biggi Token")
        Ownable(initialOwner)
    {}

    function setReserve(address _reserve) external onlyOwner {
        require(_reserve != address(0), "reserve=0");
        emit ReserveSet(reserveAddr, _reserve);
        reserveAddr = _reserve;
    }

    function setDripDistributor(address _drip) external onlyOwner {
        require(_drip != address(0), "drip=0");
        emit DripDistributorSet(dripDistributorAddr, _drip);
        dripDistributorAddr = _drip;
    }

    function setTokenRewards(address _rewards) external onlyOwner {
        require(_rewards != address(0), "rewards=0");
        emit TokenRewardsSet(tokenRewardsAddr, _rewards);
        tokenRewardsAddr = _rewards;
    }

    function setMarketingSupport(address _marketingSupport) external onlyOwner {
        require(_marketingSupport != address(0), "marketing=0");
        emit MarketingSupportSet(marketingSupportAddr, _marketingSupport);
        marketingSupportAddr = _marketingSupport;
    }

    function setRewardsOperator(address _op) external onlyOwner {
        emit RewardsOperatorSet(rewardsOperator, _op);
        rewardsOperator = _op;
    }

    function setSupplyController(address controller) external onlyOwner {
        require(controller != address(0), "controller=0");
        emit SupplyControllerSet(supplyController, controller);
        supplyController = controller;
    }

    function setSupplyGuardian(address g) external onlyOwner {
        require(g != address(0), "guardian=0");
        emit SupplyGuardianSet(supplyGuardian, g);
        supplyGuardian = g;
    }

    function setGuardianMintPaused(bool paused_) external onlyOwner {
        guardianMintPaused = paused_;
        emit GuardianMintPauseSet(paused_);
    }

    modifier onlySupplyAuthority() {
        require(msg.sender == supplyController || msg.sender == supplyGuardian, "not supply authority");
        _;
    }

    function initialDistribute() external onlyOwner {
        require(!distributed, "already distributed");
        require(
            reserveAddr != address(0) &&
            dripDistributorAddr != address(0) &&
            tokenRewardsAddr != address(0) &&
            marketingSupportAddr != address(0),
            "addrs not set"
        );

        uint256 reserveAmt = BiggiCapsLib.RESERVE_INITIAL;
        uint256 dripAmt    = BiggiCapsLib.DRIP_DISTRIBUTOR_CAP;
        uint256 rewardsAmt = BiggiCapsLib.TOKEN_REWARDS_CAP;
        uint256 marketingAmt = BiggiCapsLib.MARKETING_SUPPORT_INITIAL;

        require(totalSupply() + reserveAmt + dripAmt + rewardsAmt + marketingAmt <= CAP, "cap exceeded");

        _mint(reserveAddr, reserveAmt);
        _mint(dripDistributorAddr, dripAmt);
        IBiggiDripDistributorNotify(dripDistributorAddr).notifyTokenMint(dripAmt);
        _mint(tokenRewardsAddr, rewardsAmt);
        _mint(marketingSupportAddr, marketingAmt);

        distributed = true;
        emit InitialDistribution(
            reserveAddr,
            dripDistributorAddr,
            tokenRewardsAddr,
            marketingSupportAddr,
            reserveAmt,
            dripAmt,
            rewardsAmt,
            marketingAmt
        );
    }

    function transferFromReserveTo(address to, uint256 amount) external onlyOwner {
        require(reserveAddr != address(0), "reserve not set");
        require(to != address(0), "to0");
        require(amount > 0, "zero amount");
        require(balanceOf(reserveAddr) >= amount, "insufficient reserve balance");
        _transfer(reserveAddr, to, amount);
        emit ReserveTransfer(to, amount, msg.sender);
    }

    function refillRewardsIfBelow(uint256 minBalance, uint256 targetBalance) external {
        require(msg.sender == rewardsOperator, "only rewardsOperator");
        require(tokenRewardsAddr != address(0), "tokenRewards not set");
        require(targetBalance > minBalance, "bad targets");

        uint256 balBefore = balanceOf(tokenRewardsAddr);
        if (balBefore >= minBalance) {
            emit RewardsRefilled(balBefore, balBefore, 0);
            return;
        }

        uint256 toMint = targetBalance - balBefore;
        require(totalSupply() + toMint <= CAP, "cap exceeded");
        _mint(tokenRewardsAddr, toMint);
        emit RewardsRefilled(balBefore, balanceOf(tokenRewardsAddr), toMint);
    }

    function mint(address to, uint256 amount) external onlyOwner {
        require(totalSupply() + amount <= CAP, "cap exceeded");
        _mint(to, amount);
    }

    function mintToDripDistributor(uint256 amount) external onlySupplyAuthority {
        require(!guardianMintPaused, "guardian mint paused");
        require(dripDistributorAddr != address(0), "drip not set");
        require(guardianDexMinted + amount <= BiggiCapsLib.GUARDIAN_DEX_MINT_CAP, "DEX_CAP");
        require(totalSupply() + amount <= CAP, "cap exceeded");
        guardianDexMinted += amount;
        _mint(dripDistributorAddr, amount);
        IBiggiDripDistributorNotify(dripDistributorAddr).notifyTokenMint(amount);
        emit GuardianDexMint(dripDistributorAddr, amount, guardianDexMinted);
    }

    function mintToTokenRewards(uint256 amount) external onlySupplyAuthority {
        require(!guardianMintPaused, "guardian mint paused");
        require(tokenRewardsAddr != address(0), "tokenRewards not set");
        require(guardianRewardsMinted + amount <= BiggiCapsLib.GUARDIAN_REWARDS_MINT_CAP, "REWARDS_CAP");
        require(totalSupply() + amount <= CAP, "cap exceeded");
        guardianRewardsMinted += amount;
        _mint(tokenRewardsAddr, amount);
        emit GuardianRewardsMint(tokenRewardsAddr, amount, guardianRewardsMinted);
    }

    function pause() external onlyOwner { _pause(); }
    function unpause() external onlyOwner { _unpause(); }

    function _update(address from, address to, uint256 value) internal override {
        require(!paused(), "token transfer while paused");
        super._update(from, to, value);
    }

    function remainingMintable() external view returns (uint256) { return CAP - totalSupply(); }
    function tokenMeta() external view returns (string memory name_, string memory symbol_, uint8 decimals_) {
        return (name(), symbol(), 18);
    }

    function rescueERC20(address token, address to, uint256 amount) external onlyOwner {
        require(to != address(0), "to0");
        IERC20(token).safeTransfer(to, amount);
        emit RescueERC20(token, to, amount);
    }
}

